  helloHelp: { en: 'Hello! Can I help?', es: '¡Hola! ¿Te puedo ayudar?', ca: 'Hola! Et puc ajudar?', gl: 'Ola! Podo axudarche?', eu: 'Kaixo! Lagundu al diezazuket?' },
  assistantWelcome: { en: 'Hello! I’m Globi, Tracketeo’s helper. Ask me how to upload, organize, animate, plan or analyze your routes.', es: '¡Hola! Soy Globi, la ayuda de Tracketeo. Pregúntame cómo subir, organizar, animar, planificar o analizar tus rutas.', ca: 'Hola! Soc en Globi, l’ajuda de Tracketeo. Pregunta’m com pujar, organitzar, animar, planificar o analitzar les teves rutes.', gl: 'Ola! Son Globi, a axuda de Tracketeo. Pregúntame como cargar, organizar, animar, planificar ou analizar as túas rutas.', eu: 'Kaixo! Globi naiz, Tracketeoren laguntzailea. Galdetu nola kargatu, antolatu, animatu, planifikatu edo aztertu ibilbideak.' },
  assistantTryLater: { en: 'I cannot answer right now. Try again later.', es: 'No puedo responder ahora mismo. Inténtalo un poco más tarde.', ca: 'Ara mateix no puc respondre. Torna-ho a provar més tard.', gl: 'Non podo responder agora mesmo. Téntao máis tarde.', eu: 'Ezin dut orain erantzun. Saiatu berriro geroago.' },
