  gateGuestBody: { en: 'You have seen the first half. Create a free account and confirm your email to start full animations.', es: 'Has visto la primera mitad. Crea una cuenta gratis y confirma tu correo para iniciar animaciones completas.', ca: 'Has vist la primera meitat. Crea un compte gratuït i confirma el correu per iniciar animacions completes.', gl: 'Viches a primeira metade. Crea unha conta gratis e confirma o correo para iniciar animacións completas.', eu: 'Lehen erdia ikusi duzu. Sortu doako kontua eta baieztatu posta helbidea animazio osoak hasteko.' },
  gateCooldownPrefix: { en: 'With a free account you can complete one animation every 15 days. You can do so again in', es: 'Con tu cuenta gratis puedes completar una animación cada 15 días. Podrás volver a hacerlo en', ca: 'Amb el compte gratuït pots completar una animació cada 15 dies. Podràs tornar a fer-ho d’aquí a', gl: 'Coa conta gratis podes completar unha animación cada 15 días. Poderás volver facelo en', eu: 'Doako kontuarekin animazio bat osa dezakezu 15 egunean behin. Berriro egin ahal izango duzu' },
