  technicalReportSaved: { en: 'Technical analysis saved and linked to the route. AI did not generate the report; no credit was used.', es: 'Análisis técnico guardado y vinculado a la ruta. La IA no generó el informe; no se descontó ningún uso.', ca: 'Anàlisi tècnica desada i vinculada a la ruta. La IA no ha generat l’informe; no s’ha descomptat cap ús.', gl: 'Análise técnica gardada e vinculada á ruta. A IA non xerou o informe; non se descontou ningún uso.', eu: 'Analisi teknikoa gorde eta ibilbideari lotu zaio. IAk ez du txostena sortu; ez da erabilerarik deskontatu.' },
  analysisSavedCharged: { en: 'Analysis saved and linked to the route. One credit was used.', es: 'Análisis guardado y vinculado a la ruta. Se descontó 1 uso del saldo.', ca: 'Anàlisi desada i vinculada a la ruta. S’ha descomptat 1 ús del saldo.', gl: 'Análise gardada e vinculada á ruta. Descontouse 1 uso do saldo.', eu: 'Analisia gorde eta ibilbideari lotu zaio. Kreditu bat erabili da.' },
